import { createEffect, createSignal, For, Match, ParentComponent, Show, Switch } from "solid-js";

import { getWarStatusFromPlayerId, WarStatus } from "#core/ui/utilities/diplomacy-utilities.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { RelationshipBreakdown } from "#base/ui-next/components/relationship-breakdown.jsx";

export interface RelationshipTooltipProps {
	playerId: PlayerId;
}

interface AgendaItem {
	name: string;
	description: string;
}

const RelationshipTooltipComponent: ParentComponent<RelationshipTooltipProps> = (props) => {
	const [playerName, setPlayerName] = createSignal<string>("");
	const [warStatus, setWarStatus] = createSignal<WarStatus>({ isAtWar: false, warSupport: 0 });

	const [agendaItems, setAgendaItems] = createSignal<AgendaItem[]>([]);

	createEffect(() => {
		setWarStatus(getWarStatusFromPlayerId(props.playerId));
		const player = Players.get(props.playerId);
		if (!player) {
			console.error(
				"relationship-tooltip: Attempting to update relationship info screen, but unable to get selected player library",
			);
			return;
		}
		setPlayerName(player.name);

		if (!player.isAI) {
			return;
		}

		const agendaItemList: AgendaItem[] = [];
		const agendaNames = Game.Diplomacy.getAgendaNames(props.playerId);
		const agendaDescriptions = Game.Diplomacy.getAgendaDescriptions(props.playerId);
		for (let i = 0; i < agendaNames.length; i++) {
			agendaItemList.push({ name: agendaNames[i], description: agendaDescriptions[i] });
		}
		setAgendaItems(agendaItemList);
	});
	return (
		<Tooltip>
			<Tooltip.Trigger>
				<div>{props.children}</div>
			</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame
					class="fxs-tooltip fxs-relationship-tooltip"
					data-name="Relationship-Tooltip"
				>
					<div class="flex flex-col justify-center w-full">
						<Show when={warStatus().isAtWar}>
							<div class="text-sm font-title">
								<L10n.Compose text="LOC_DIPLOMACY_WAR_WEARINESS" />
							</div>
							<div class="font-body text-xs min-w-72">
								<Switch fallback={<L10n.Stylize text={"LOC_WAR_TOOLTIP_NO_WAR_WEARINESS"} />}>
									<Match when={warStatus().warSupport < 0}>
										<L10n.Stylize
											text="LOC_WAR_TOOLTIP_RECEIVING_WAR_WEARINESS"
											args={[playerName()]}
										/>
									</Match>
									<Match when={warStatus().warSupport > 0}>
										<L10n.Stylize
											text="LOC_WAR_TOOLTIP_GIVING_WAR_WEARINESS"
											args={[playerName()]}
										/>
									</Match>
								</Switch>
							</div>
						</Show>
						<Show when={!warStatus().isAtWar}>
							<RelationshipBreakdown playerId={props.playerId} />
							<div class="fxs-relationship-tooltip__agenda">
								<L10n.Stylize
									class="fxs-relationship-tooltip__agenda-title text-sm text-victory-economic self-center"
									text="LOC_DIPLOMACY_AGENDA_TITLE"
								/>
								<For each={agendaItems()}>
									{(agendaItem, index) => (
										<div classList={{ "mb-2": index() + 1 < agendaItems().length }}>
											<L10n.Stylize
												class="fxs-relationship-tooltip__agenda-name text-base self-center"
												text={agendaItem.name}
											/>
											<L10n.Stylize
												class="fxs-relationship-tooltip__agenda-description text-sm"
												text={agendaItem.description}
											/>
										</div>
									)}
								</For>
							</div>
						</Show>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const RelationshipTooltip = ComponentRegistry.register({
	name: "RelationshipTooltip",
	createInstance: RelationshipTooltipComponent,
});
